<template><main class="page"><a-card class="glass-card card" :bordered="false"><a-button @click="router.push('/')">← 首页</a-button><a-spin :spinning="loading"><a-result v-if="error" status="404" title="分享不可用" :sub-title="error"/><template v-else-if="trip"><h1>{{trip.title||`${trip.city}行程`}}</h1><p>{{trip.start_date}} 至 {{trip.end_date}} · {{trip.outcome}}</p><a-card v-for="day in trip.plan?.days||[]" :key="day.day_index" :title="`第 ${day.day_index+1} 天 · ${day.date}`" class="day"><a-timeline><a-timeline-item v-for="poi in day.attractions" :key="poi.poi_id"><strong>{{poi.name}}</strong><br>{{poi.address}}</a-timeline-item></a-timeline></a-card><a-button v-if="logged" type="primary" @click="copy">复制到我的行程</a-button></template></a-spin></a-card></main></template>
<script setup lang="ts">import{ref,onMounted}from'vue';import{useRoute,useRouter}from'vue-router';import{message}from'ant-design-vue';import{fetchSharedTrip,copySharedTrip}from'@/services/api';import{isAuthenticated}from'@/services/auth';const route=useRoute(),router=useRouter(),token=String(route.params.token),trip=ref<any>(),loading=ref(true),error=ref(''),logged=isAuthenticated();onMounted(async()=>{try{trip.value=(await fetchSharedTrip(token)).data}catch(e:any){error.value=e?.response?.data?.message||'链接已过期或被撤销'}finally{loading.value=false}});async function copy(){const r=await copySharedTrip(token);message.success(r.message);router.push('/history')}
</script>
<style scoped>.page{padding:36px;min-height:100vh}.card{max-width:900px;margin:auto;border-radius:22px}.day{margin:16px 0}@media(max-width:700px){.page{padding:12px}}</style>
